import { HistorySentTime } from "@/app/(app)/history/history-sent-time";
import { StatusBadge } from "./StatusBadge";
import { RowActions, type ShortlistState } from "./RowActions";
import styles from "./history.module.css";
export type HistoryMessage = {
  id: string;
  contactId: string;
  recipientName: string;
  recipientEmail: string;
  recipientRole: string | null;
  recipientCompany: string | null;
  templateName: string | null;
  sentAt: Date | null;
  status: string;
  deliveryState: string;
  dispatchedAt: Date | null;
  error: string | null;
};
export function HistoryRow({
  message: s,
  shortlist,
}: {
  message: HistoryMessage;
  shortlist: ShortlistState;
}) {
  return (
    <tr
      className={`${styles.row} grid grid-cols-[minmax(0,_2.2fr)_minmax(0,_1.9fr)_minmax(0,_1.1fr)_minmax(0,_1fr)_minmax(0,_1.1fr)_84px] items-center gap-3.5 py-3.5 px-5 border-t border-dotted border-separator [@media(max-width:_859px)]:grid-cols-[minmax(0,_1fr)_84px] [@media(max-width:_859px)]:gap-y-2.5`}
      role="row"
    >
      <td role="cell">
        <div className="flex gap-3 items-center min-w-0">
          <span
            className={`${styles.avatar} grid place-items-center shrink-0 w-10 h-10 rounded-[50%] [background:var(--appearance-primary,_linear-gradient(_135deg,_var(--color-history-h-purple-13),_var(--color-history-h-pink-14)))] text-[var(--appearance-on-primary,_var(--color-history-color-21))] font-extrabold`}
            aria-hidden="true"
          >
            {(s.recipientName.trim() || s.recipientEmail)
              .charAt(0)
              .toUpperCase()}
          </span>
          <div className="min-w-0">
            <p className="break-words font-bold">{s.recipientName}</p>
            <p className="block overflow-hidden text-ellipsis whitespace-nowrap text-[var(--h-muted)] text-[13px]">
              {s.recipientEmail}
            </p>
          </div>
        </div>
      </td>
      <td role="cell">
        <span
          className={`${styles.role} inline-block max-w-full py-[3px] px-[11px] rounded-full [background:var(--appearance-wash,_var(--color-history-background-22))] text-[12.5px] font-semibold`}
        >
          {s.recipientRole?.trim() || "—"}
        </span>
        <p className="mt-1 text-[13px]">
          <span className={`${styles.company} text-[var(--h-muted)]`}>
            {s.recipientCompany?.trim() || "—"}
          </span>
        </p>
      </td>
      <td role="cell">
        <span
          className={`${styles.template} [font:500_12px_var(--font-jetbrains),_monospace] text-[var(--h-muted)]`}
        >
          {s.templateName || "—"}
        </span>
      </td>
      <td role="cell">
        <HistorySentTime value={s.sentAt?.toISOString() ?? null} />
      </td>
      <td role="cell">
        <StatusBadge
          status={s.status}
          deliveryState={s.deliveryState}
          error={s.error}
          dispatchedAt={s.dispatchedAt}
        />
      </td>
      <td role="cell">
        <RowActions id={s.id} status={s.status} shortlist={shortlist} />
      </td>
    </tr>
  );
}
